interface Shape { area(): number; name: string }
class Animal { name: string; constructor(name: string) { this.name = name; } speak(): string { return this.name; } }
class Dog extends Animal { tricks: string[] = ["sit"]; speak(): string { return "woof " + this.name; } }
class Circle implements Shape { r: number; name = "c"; constructor(r: number) { this.r = r; } area(): number { return 3 * this.r; } }
function main(): void {
  const d = new Dog("Rex");
  const a: Animal = d;
  const xs: Animal[] = [new Animal("Cat"), d];
  console.log(a, xs);
  const s: Shape = new Circle(2);
  const shapes: Shape[] = [new Circle(1)];
  console.log(s, shapes, s.constructor.name, shapes[0].constructor.name);
  const plain: Shape = { name: "p", area: () => 1 };
  console.log(plain.name);
}
